import { localizedPrice } from "@/lib/localized-price";
import { Suspense } from "react";
import { requireUser } from "@/lib/session";
import { readEntitlements } from "@/lib/entitlements";
import { readContacts } from "@/lib/shortlist";
import { db } from "@/lib/db";
import { pageNumber } from "@/lib/params";
import { WorkspaceSkeleton } from "@/components/workspace-skeleton";
import { ContactsSearch } from "@/components/contacts/ContactsSearch";
import { ContactList } from "@/components/contacts/ContactList";
import { ImportContacts } from "@/components/contacts/ImportContacts";
import { NewContactForm } from "@/components/contacts/NewContactForm";
import styles from "@/components/contacts/contacts.module.css";

export const metadata = { title: "Contacts" };
async function ContactsContent({
  searchParams,
}: {
  searchParams: Promise<{ edit?: string; q?: string; page?: string }>;
}) {
  const user = await requireUser();
  const params = await searchParams;
  const q = (params.q ?? "").slice(0, 160);
  const page = pageNumber(params.page);
  const [contactPage, existing, editing, premiumPrice, access] =
    await Promise.all([
      readContacts(user.id, q, page),
      db.contact.findMany({
        where: { userId: user.id },
        select: { email: true },
      }),
      params.edit
        ? db.contact.findFirst({
            where: { id: params.edit, userId: user.id, archivedAt: null },
          })
        : null,
      localizedPrice(Promise.resolve({})),
      readEntitlements(user.id),
    ]);
  const { contacts, total } = contactPage;
  return (
    <div
      className={`workspace-mono:gap-7 workspace-mono:min-[900px]:grid-cols-[minmax(0,1fr)_350px] workspace-mono:min-[1200px]:grid-cols-[minmax(0,1fr)_380px] workspace-mono:[@media(max-width:899px)]:gap-6 grid grid-cols-1 items-start gap-6 min-[900px]:grid-cols-[minmax(0,1fr)_370px]`}
    >
      <section aria-label="Contacts list and import" className="min-w-0">
        <ContactsSearch query={q} />
        <p
          className={`workspace-mono:max-w-[70ch] workspace-mono:mt-3 workspace-mono:mb-4.5 workspace-mono:text-[12px] workspace-mono:leading-[1.6] mt-3 mb-5 text-[13px] text-[var(--contacts-muted)]`}
        >
          {access.features.historyShortlist
            ? "Sent contacts move to History. Use + in History to add them to your shortlist and email them again."
            : "Sent contacts move to History. To email someone again, enter and save their details in Contacts to add them back to your shortlist."}
        </p>
        <ContactList
          contacts={contacts}
          total={total}
          page={page}
          query={q}
          hasContacts={existing.length > 0}
        />
        <ImportContacts
          roles={user.preferredRoles}
          existingEmails={existing.map((c) => c.email)}
        />
      </section>
      <NewContactForm
        key={editing?.id ?? "new"}
        premiumPrice={premiumPrice}
        contact={editing ?? undefined}
        roles={user.preferredRoles}
      />
    </div>
  );
}

export default function Contacts(props: Parameters<typeof ContactsContent>[0]) {
  return (
    <div className={`${styles.page} text-[var(--contacts-text)]`}>
      <header className="workspace-screen-heading mb-8 pt-4 workspace-mono:pt-2 workspace-mono:mb-6.5">
        <p className="font-mono text-[11.5px] font-medium tracking-[.14em] text-[var(--contacts-purple)] uppercase workspace-mono:text-[var(--coral)]">
          People worth reaching out to
        </p>
        <h1 className="mt-2 text-[clamp(30px,4.6vw,46px)] leading-[1.08] font-extrabold tracking-[-.04em]">
          Contacts
        </h1>
        <p className="mt-2 text-[var(--contacts-muted)]">
          Build your shortlist, one person or one CSV at a time.
        </p>
      </header>
      <Suspense
        fallback={<WorkspaceSkeleton page="contacts" heading={false} />}
      >
        <ContactsContent {...props} />
      </Suspense>
    </div>
  );
}
